-- 100
SELECT CAST(SUM(CASE WHEN USERS.REPUTATION > 1000 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(POSTS.ID) AS PERCENTAGE FROM POSTS INNER JOIN USERS ON POSTS.OWNERUSERID = USERS.ID;
-- ----------sql2------------
-- 0
