-- ----------sql1------------
-- 1
SELECT CAST(SUM(CASE WHEN NOT T2.TIME IS NULL THEN 1 ELSE 0 END) AS REAL) / COUNT(*) AS RATE FROM RACES AS T1 INNER JOIN RESULTS AS T2 ON T1.RACEID = T2.RACEID WHERE T1.NAME = 'AUSTRALIAN GRAND PRIX' AND T1.YEAR = 2008;
-- ----------sql2------------
-- 100
SELECT CAST(SUM(IIF(T1.TIME IS NOT NULL, 1, 0)) AS REAL) * 100 / COUNT(T1.RESULTID) FROM RESULTS AS T1 INNER JOIN RACES AS T2 ON T1.RACEID = T2.RACEID WHERE T2.NAME = 'AUSTRALIAN GRAND PRIX' AND T2.YEAR = 2008;

