SELECT T1.NAME FROM LEAGUE AS T1 INNER JOIN MATCH AS T2 ON T1.ID = T2.LEAGUE_ID WHERE T2.SEASON = '2008/2009' GROUP BY T1.NAME ORDER BY COUNT(*) DESC LIMIT 1;
-- ----------sql2------------
