-- 2147483649
SELECT L.NAME FROM LEAGUE AS L INNER JOIN (SELECT LEAGUE_ID, COUNT(ID) AS MATCH_COUNT FROM MATCH WHERE SEASON = '2015/2016' GROUP BY LEAGUE_ID) AS M ON L.ID = M.LEAGUE_ID ORDER BY M.MATCH_COUNT DESC LIMIT 4;
-- ----------sql2------------
